def can_partition_k_subsets(nums,k):
    if sum(nums)%k:return False
    target=sum(nums)//k;bins=[0]*k
    for value in sorted(nums,reverse=True):
        for bucket in range(k):
            if bins[bucket]+value<=target:
                bins[bucket]+=value
                break
        else:return False
    return all(value==target for value in bins)
